import{bV as r,aL as e,u as a,G as o}from"./chunks/framework.BfzMay2U.js";const b=JSON.parse('{"title":"制造业 PHP 面试题：测试、上线与需求协作（151—180）","description":"","frontmatter":{"title":"制造业 PHP 面试题：测试、上线与需求协作（151—180）","date":"2026-11-15T10:50:00.000Z","categories":["面试","PHP"],"tags":["测试","软件验证","上线运维","需求分析","文档","故障排查"],"sidebarSort":6},"headers":[],"relativePath":"php/jd/delivery-troubleshooting-interview.md","filePath":"php/jd/delivery-troubleshooting-interview.md"}'),s={name:"php/jd/delivery-troubleshooting-interview.md"};function n(d,t,l,i,h,p){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="制造业-php-面试题-测试、上线与需求协作-151—180" tabindex="-1">制造业 PHP 面试题：测试、上线与需求协作（151—180） <a class="header-anchor" href="#制造业-php-面试题-测试、上线与需求协作-151—180" aria-label="Permalink to &quot;制造业 PHP 面试题：测试、上线与需求协作（151—180）&quot;">​</a></h1><p>本篇对应 JD 中“独立交付、异常排查、需求转化、测试验证、受控发布与文档沉淀”。场景回答建议采用“事实与影响 → 定位证据 → 处理动作 → 验证及后续改进”的顺序。</p><h2 id="一、测试验证与交付证据" tabindex="-1">一、测试验证与交付证据 <a class="header-anchor" href="#一、测试验证与交付证据" aria-label="Permalink to &quot;一、测试验证与交付证据&quot;">​</a></h2><h3 id="_151-单元测试、集成测试、端到端测试和-uat-有何区别" tabindex="-1">151. 单元测试、集成测试、端到端测试和 UAT 有何区别？ <a class="header-anchor" href="#_151-单元测试、集成测试、端到端测试和-uat-有何区别" aria-label="Permalink to &quot;151. 单元测试、集成测试、端到端测试和 UAT 有何区别？&quot;">​</a></h3><p><strong>参考回答：</strong> 单元测试验证局部业务规则，集成测试验证数据库、接口与组件协作，端到端测试验证用户关键流程，UAT 由业务按真实场景确认是否满足使用目标。它们覆盖不同风险，不能用一项通过替代其他必要验证。</p><p><strong>追问要点：</strong> 不必追求所有代码同样多测试，应优先覆盖扣料、权限、状态、审计和接口异常等高影响规则。</p><h3 id="_152-如何为一个报工功能制定完整测试矩阵" tabindex="-1">152. 如何为一个报工功能制定完整测试矩阵？ <a class="header-anchor" href="#_152-如何为一个报工功能制定完整测试矩阵" aria-label="Permalink to &quot;152. 如何为一个报工功能制定完整测试矩阵？&quot;">​</a></h3><p><strong>参考回答：</strong> 从角色、工厂、状态、数量边界、工序前置、物料、质量和网络故障等维度选择有意义的组合。覆盖正常、重复、同键冲突、越权、并发超量、库存不足、事务失败和外部超时，同时核对数据库副作用与审计结果。</p><p><strong>追问要点：</strong> “全场景”不是穷举无限组合，应记录风险与覆盖依据，保留关键边界、异常和现实操作路径的测试证据。</p><h3 id="_153-怎么验证-两个请求同时提交也只扣一次料" tabindex="-1">153. 怎么验证“两个请求同时提交也只扣一次料”？ <a class="header-anchor" href="#_153-怎么验证-两个请求同时提交也只扣一次料" aria-label="Permalink to &quot;153. 怎么验证“两个请求同时提交也只扣一次料”？&quot;">​</a></h3><p><strong>参考回答：</strong> 使用真实 MySQL 和两个独立请求或连接，在接近同一时刻提交同一个幂等键，再查询报工、消耗和库存流水，确认只形成一次业务效果。另用两个不同键争抢不足以同时满足的库存，验证至少一方被拒绝且库存不为负。</p><p><strong>追问要点：</strong> 在同一数据库连接顺序调用两次不是并发测试；仅检查 HTTP 成功次数也不能证明库存正确。</p><h3 id="_154-第三方接口无法随时调用-怎样测试" tabindex="-1">154. 第三方接口无法随时调用，怎样测试？ <a class="header-anchor" href="#_154-第三方接口无法随时调用-怎样测试" aria-label="Permalink to &quot;154. 第三方接口无法随时调用，怎样测试？&quot;">​</a></h3><p><strong>参考回答：</strong> 在本地通过框架 Fake 或既有客户端边界模拟成功、超时、错误码、响应缺字段、重复和状态未知，验证本地决策。联调环境再用供应商沙箱或批准样例核对签名、字段及真实业务状态，保留契约与版本。</p><p><strong>追问要点：</strong> Mock 只证明代码按假设工作，不能证明假设与供应商一致。接口契约变化应触发回归。</p><h3 id="_155-uat-发现的问题与需求变更如何区分" tabindex="-1">155. UAT 发现的问题与需求变更如何区分？ <a class="header-anchor" href="#_155-uat-发现的问题与需求变更如何区分" aria-label="Permalink to &quot;155. UAT 发现的问题与需求变更如何区分？&quot;">​</a></h3><p><strong>参考回答：</strong> 对照已确认的验收规则和样例，不满足约定的是缺陷，新增规则或改变目标可能是需求变更。若原规则含糊，先确认业务目标和影响，记录共同决议，再评估修改、回归和上线安排，避免只凭开发者个人解释。</p><p><strong>追问要点：</strong> 重要质量风险不能因为文档没写就忽略，应提出影响并交由相应责任人决定控制措施。</p><h3 id="_156-软件测试和软件验证是一回事吗" tabindex="-1">156. 软件测试和软件验证是一回事吗？ <a class="header-anchor" href="#_156-软件测试和软件验证是一回事吗" aria-label="Permalink to &quot;156. 软件测试和软件验证是一回事吗？&quot;">​</a></h3><p><strong>参考回答：</strong> 测试提供某些条件下行为的证据，验证还需证明软件适合既定用途，通常结合需求、风险、设计、测试、缺陷关闭和运行控制。医疗制造系统的具体过程与交付物由质量体系和适用要求确定，开发负责提供可追踪的技术证据。</p><p><strong>追问要点:</strong> 不把“用例全部通过”或“测试覆盖率高”直接等同于适用性和合规性结论. FDA 的 CSA 指南采用风险导向的软件保证方法, 不要求所有功能使用相同测试强度, 也不意味着可以不保留适用的客观证据; 其使用范围及来源见 <a href="./mes-edhr-oa-interview.html#_118-采用-csa-不需要测试脚本和证据了-正确吗">MES 篇第 118 题</a>.</p><h3 id="_157-需求追踪矩阵怎么做才有用" tabindex="-1">157. 需求追踪矩阵怎么做才有用？ <a class="header-anchor" href="#_157-需求追踪矩阵怎么做才有用" aria-label="Permalink to &quot;157. 需求追踪矩阵怎么做才有用？&quot;">​</a></h3><p><strong>参考回答：</strong> 将需求编号关联到风险、控制措施、实现版本、测试用例与结果，缺陷修复后补复测证据。例如“重复报工不得重复扣料”关联唯一约束、事务设计、并发用例和库存核对结果。矩阵用于找遗漏及评估变更影响。</p><p><strong>追问要点：</strong> 不必为小改动堆大量文档，但关键控制要能找到证据；需求删除、规则变更也要更新关联，不只在首次上线填写。</p><h3 id="_158-权限和审计应该测试哪些负向场景" tabindex="-1">158. 权限和审计应该测试哪些负向场景？ <a class="header-anchor" href="#_158-权限和审计应该测试哪些负向场景" aria-label="Permalink to &quot;158. 权限和审计应该测试哪些负向场景？&quot;">​</a></h3><p><strong>参考回答：</strong> 验证未登录、已停用、越工厂、低权限调用高权限接口、改 URL 读取附件、批量导出越权、创建人自审和任务执行时权限变化。审计检查成功动作、规定需要记录的失败尝试、前后值、原因及敏感字段处理。</p><p><strong>追问要点：</strong> 拒绝动作不能留下半条业务写入；审计写入失败时是否阻断业务要由记录重要性与设计要求明确。</p><h2 id="二、发布、监控与故障处理" tabindex="-1">二、发布、监控与故障处理 <a class="header-anchor" href="#二、发布、监控与故障处理" aria-label="Permalink to &quot;二、发布、监控与故障处理&quot;">​</a></h2><h3 id="_159-一个受控发布清单最少包含什么" tabindex="-1">159. 一个受控发布清单最少包含什么？ <a class="header-anchor" href="#_159-一个受控发布清单最少包含什么" aria-label="Permalink to &quot;159. 一个受控发布清单最少包含什么？&quot;">​</a></h3><p><strong>参考回答：</strong> 变更范围、版本与构建产物、测试和缺陷状态、数据库脚本、配置与密钥引用、依赖系统、备份、执行人、批准记录、窗口、验证步骤及回退条件。按团队实际流程控制，生产操作使用最小权限并记录结果。</p><p><strong>追问要点：</strong> 版本号要能对应具体代码和配置，不能现场手工改一份无人知道来源的文件后宣称发布完成。</p><h3 id="_160-laravel-更新代码后-为什么后台任务还跑旧逻辑" tabindex="-1">160. Laravel 更新代码后，为什么后台任务还跑旧逻辑？ <a class="header-anchor" href="#_160-laravel-更新代码后-为什么后台任务还跑旧逻辑" aria-label="Permalink to &quot;160. Laravel 更新代码后，为什么后台任务还跑旧逻辑？&quot;">​</a></h3><p><strong>参考回答：</strong> 队列 worker 是长驻进程，可能仍持有旧代码；还可能存在旧容器、配置或路由缓存未更新。发布时按部署方式重新加载进程与缓存，确保当前任务和新任务的切换受控，并监控 worker 是否实际完成切换。</p><p><strong>追问要点：</strong> 不能直接强杀所有长任务而不考虑重投；新旧 Job 数据结构要兼容仍在队列中的历史消息。</p><h3 id="_161-回滚代码为什么不等于回滚系统" tabindex="-1">161. 回滚代码为什么不等于回滚系统？ <a class="header-anchor" href="#_161-回滚代码为什么不等于回滚系统" aria-label="Permalink to &quot;161. 回滚代码为什么不等于回滚系统？&quot;">​</a></h3><p><strong>参考回答：</strong> 数据库结构与数据、已发出的 ERP 请求、文件和消息不会随代码自动回到过去。回退方案必须区分应用回退、数据修复、功能关闭和业务补偿，优先采用兼容的数据库变更，明确不可逆动作。</p><p><strong>追问要点：</strong> 已新增且被使用的字段不能直接删除；已入库的真实业务单据通常要受控冲销，不能恢复旧库覆盖后续合法数据。</p><h3 id="_162-上线后应该监控哪些指标" tabindex="-1">162. 上线后应该监控哪些指标？ <a class="header-anchor" href="#_162-上线后应该监控哪些指标" aria-label="Permalink to &quot;162. 上线后应该监控哪些指标？&quot;">​</a></h3><p><strong>参考回答：</strong> 监控请求错误率与延迟分位数、FPM 与应用容量、数据库连接和锁等待、队列积压年龄、同步成功与未知状态、设备心跳、对账差异，以及关键业务量。为高影响问题设置可执行的告警入口和责任人。</p><p><strong>追问要点：</strong> 平均耗时掩盖慢请求，应关注 p95、p99 等分位数；阈值根据业务窗口和容量基线确定，不随意给所有系统套同一数字。</p><h3 id="_163-用户说-报工点了没反应-怎样排查" tabindex="-1">163. 用户说“报工点了没反应”，怎样排查？ <a class="header-anchor" href="#_163-用户说-报工点了没反应-怎样排查" aria-label="Permalink to &quot;163. 用户说“报工点了没反应”，怎样排查？&quot;">​</a></h3><p><strong>参考回答：</strong> 先收集时间、账号、工单、终端与请求 ID，检查本地是否待同步、请求是否发出、后端是否接收及最终状态。沿网关、Laravel、SQL、队列和 ERP 查耗时与错误，再用业务键确认是否已经成功，避免引导重复提交。</p><p><strong>追问要点：</strong> 若操作已成功而页面超时，应修正反馈或补充结果查询；若确未接收，再按原键安全重试，不能直接新建报工记录。</p><h3 id="_164-队列突然大量积压-你会怎么办" tabindex="-1">164. 队列突然大量积压，你会怎么办？ <a class="header-anchor" href="#_164-队列突然大量积压-你会怎么办" aria-label="Permalink to &quot;164. 队列突然大量积压，你会怎么办？&quot;">​</a></h3><p><strong>参考回答：</strong> 比较进入速率、消费速率、最老任务年龄和失败类型，检查 worker、数据库、外部接口、限流及重试风暴。先保护生产关键链路，暂停低优先级任务或故障依赖的无效重试，再按瓶颈和下游容量恢复消费。</p><p><strong>追问要点：</strong> 增加 worker 可能扩大数据库锁竞争或把供应商打挂。恢复后验证重复消费、死信、业务延迟和对账，而不是只看队列长度归零。</p><h3 id="_165-生产数据错了-业务要求你立刻改库-怎么处理" tabindex="-1">165. 生产数据错了，业务要求你立刻改库，怎么处理？ <a class="header-anchor" href="#_165-生产数据错了-业务要求你立刻改库-怎么处理" aria-label="Permalink to &quot;165. 生产数据错了，业务要求你立刻改库，怎么处理？&quot;">​</a></h3><p><strong>参考回答：</strong> 先确认影响、权威来源、原始证据和业务恢复目标，优先走已有受控更正或冲销接口。确需数据修复时，按批准流程制定限定范围脚本、前置校验、备份、事务和核对方案，在适当环境演练，执行后留证并对账。</p><p><strong>追问要点：</strong> 不直接删日志掩盖错误，不用无限制 <code>UPDATE</code>。涉及签名记录和下游单据时，必须同步评估更正、复核与补偿。</p><h3 id="_166-故障复盘怎样避免变成-以后注意" tabindex="-1">166. 故障复盘怎样避免变成“以后注意”？ <a class="header-anchor" href="#_166-故障复盘怎样避免变成-以后注意" aria-label="Permalink to &quot;166. 故障复盘怎样避免变成“以后注意”？&quot;">​</a></h3><p><strong>参考回答：</strong> 记录影响范围、时间线、触发条件、发现和恢复过程，以日志和数据解释根因及促成因素。改进项落到具体负责人、期限和验证方法，例如补充唯一约束、增加未知状态查询和演练恢复，而不是只要求个人更仔细。</p><p><strong>追问要点：</strong> 区分立即止血和长期修复，检查改进是否生效；不要把“重启后好了”当成根因。</p><h2 id="三、需求转化、文档与面试表达" tabindex="-1">三、需求转化、文档与面试表达 <a class="header-anchor" href="#三、需求转化、文档与面试表达" aria-label="Permalink to &quot;三、需求转化、文档与面试表达&quot;">​</a></h2><h3 id="_167-业务说-加一个生产报表-你需要问什么" tabindex="-1">167. 业务说“加一个生产报表”，你需要问什么？ <a class="header-anchor" href="#_167-业务说-加一个生产报表-你需要问什么" aria-label="Permalink to &quot;167. 业务说“加一个生产报表”，你需要问什么？&quot;">​</a></h3><p><strong>参考回答：</strong> 确认使用人、决策目的、统计对象、口径、时间与班次、维度、筛选、刷新频率、权限、导出格式及最大数据量。让业务提供一份小样本和手工计算结果，再形成可验收定义。</p><p><strong>追问要点：</strong> “按车间统计良率”还需明确返工、跨班次、报废和零分母，不应直接开始写 <code>GROUP BY</code>。</p><h3 id="_168-模糊或冲突的业务规则如何结构化" tabindex="-1">168. 模糊或冲突的业务规则如何结构化？ <a class="header-anchor" href="#_168-模糊或冲突的业务规则如何结构化" aria-label="Permalink to &quot;168. 模糊或冲突的业务规则如何结构化？&quot;">​</a></h3><p><strong>参考回答：</strong> 用规则表写出条件、输入、允许动作、结果、优先级和异常，并列举冲突样例。例如“生产经理可补录”与“关闭工单禁止修改”冲突时，明确是否需要重开、审批或独立更正。由对应业务责任人确认决议后版本化。</p><p><strong>追问要点：</strong> 将事实、假设、待决项和风险分开记录；开发人员可以提出取舍建议，但不能无记录地替质量负责人决定放行规则。</p><h3 id="_169-怎样把需求拆成可以开发和验收的任务" tabindex="-1">169. 怎样把需求拆成可以开发和验收的任务？ <a class="header-anchor" href="#_169-怎样把需求拆成可以开发和验收的任务" aria-label="Permalink to &quot;169. 怎样把需求拆成可以开发和验收的任务？&quot;">​</a></h3><p><strong>参考回答：</strong> 按可交付业务动作拆分，并列数据结构、页面、接口、规则、权限、状态、审计、异常、测试和上线项。识别依赖与风险，先验证关键接口或数据规则，再完成端到端闭环，避免只按“前端、后端各一项”粗分。</p><p><strong>追问要点：</strong> 任务完成标准应是可演示的行为和证据，例如“同键重试返回原报工号且不再扣料”，而不是“代码写完”。</p><h3 id="_170-排期紧又有新需求插入-你怎样沟通" tabindex="-1">170. 排期紧又有新需求插入，你怎样沟通？ <a class="header-anchor" href="#_170-排期紧又有新需求插入-你怎样沟通" aria-label="Permalink to &quot;170. 排期紧又有新需求插入，你怎样沟通？&quot;">​</a></h3><p><strong>参考回答：</strong> 用当前范围、完成情况、依赖和风险说明影响，给出缩减非核心范围、调整顺序或延后日期等具体选择。确认优先级后更新验收和上线计划，对扣料正确性、权限及必要验证不因赶工直接省略。</p><p><strong>追问要点：</strong> 不把所有内容都标成最高优先级，也不凭感觉承诺日期；对未确认的供应商联调时间单独说明依赖。</p><h3 id="_171-多部门与供应商协作-如何推动问题闭环" tabindex="-1">171. 多部门与供应商协作，如何推动问题闭环？ <a class="header-anchor" href="#_171-多部门与供应商协作-如何推动问题闭环" aria-label="Permalink to &quot;171. 多部门与供应商协作，如何推动问题闭环？&quot;">​</a></h3><p><strong>参考回答：</strong> 一条问题记录包含业务影响、复现条件、关联编号、证据、当前定位、责任人、下一步和完成期限。定期跟进阻塞，必要时按影响升级；修复后由约定人员复测确认，关联版本和上线记录后关闭。</p><p><strong>追问要点：</strong> “已转发给供应商”不等于解决；开发可以推动技术定位，但业务规则和现场操作仍要由相应部门共同确认。</p><h3 id="_172-技术文档怎样写才方便接手" tabindex="-1">172. 技术文档怎样写才方便接手？ <a class="header-anchor" href="#_172-技术文档怎样写才方便接手" aria-label="Permalink to &quot;172. 技术文档怎样写才方便接手？&quot;">​</a></h3><p><strong>参考回答：</strong> 开发说明描述模块边界、数据模型和关键规则，接口文档描述契约与异常，部署文档给出前置条件、步骤、验证和回退，测试记录保留用例、环境、结果及缺陷，版本记录说明行为变化及迁移影响。文件要与代码版本关联并及时更新。</p><p><strong>追问要点：</strong> 密钥使用受控引用，不能贴进文档；常见故障说明要给诊断依据和处理边界，不能只写“有问题重启”。</p><h3 id="_173-哪些东西值得沉淀成组件-哪些不值得" tabindex="-1">173. 哪些东西值得沉淀成组件，哪些不值得？ <a class="header-anchor" href="#_173-哪些东西值得沉淀成组件-哪些不值得" aria-label="Permalink to &quot;173. 哪些东西值得沉淀成组件，哪些不值得？&quot;">​</a></h3><p><strong>参考回答：</strong> 已被重复验证的通用能力，例如统一请求、错误分类、字段校验和标准日志上下文，适合按现有结构复用；尚未稳定的业务差异先保留明确实现。是否抽取看重复成本、变化方向和边界清晰度，不能按代码行数决定。</p><p><strong>追问要点：</strong> 不把不同 ERP 的业务拒绝都合成一种异常，也不为了抽取公共流程丢失某个工厂特有的质量校验。</p><h3 id="_174-没有-mes、e-dhr-或-uniapp-实战经验-如何回答" tabindex="-1">174. 没有 MES、E-DHR 或 UniApp 实战经验，如何回答？ <a class="header-anchor" href="#_174-没有-mes、e-dhr-或-uniapp-实战经验-如何回答" aria-label="Permalink to &quot;174. 没有 MES、E-DHR 或 UniApp 实战经验，如何回答？&quot;">​</a></h3><p><strong>参考回答：</strong> 如实说明未交付的领域，再讲已有的可迁移能力，例如状态流转、库存并发、接口重试、权限和日志，并用本系列场景解释准备过的实现与验证方法。提出先理解现场流程、跟随现有规范完成一个小闭环的入手方式。</p><p><strong>可用表达：</strong> “我没有把准备案例当作交付经历，但能说明报工接口如何校验、如何防重和如何测试。领域规则会先与生产及质量人员确认，再落实到受控功能。”不要捏造项目规模、成果百分比或审计结论。</p><h3 id="_175-怎样用三分钟讲一个最符合这份-jd-的项目" tabindex="-1">175. 怎样用三分钟讲一个最符合这份 JD 的项目？ <a class="header-anchor" href="#_175-怎样用三分钟讲一个最符合这份-jd-的项目" aria-label="Permalink to &quot;175. 怎样用三分钟讲一个最符合这份 JD 的项目？&quot;">​</a></h3><p><strong>参考回答：</strong> 用真实项目说明业务目标、本人边界、技术方案、一次关键难题、验证和结果。技术内容围绕字段与流程、MySQL、权限、接口可靠性及上线支持展开，结果使用有依据的数量、耗时或缺陷变化，没有统计就描述可核查的交付事实。</p><p><strong>反问面试官：</strong> 可以询问现有 Laravel 与 MySQL 版本、核心系统职责、最大数据量、设备接入方式、当前故障痛点，以及质量验证和发布由谁批准。借此判断岗位更偏开发、集成还是现场运维。</p><h2 id="四、交付数据与进阶追问" tabindex="-1">四、交付数据与进阶追问 <a class="header-anchor" href="#四、交付数据与进阶追问" aria-label="Permalink to &quot;四、交付数据与进阶追问&quot;">​</a></h2><p>资料核对日期: <strong>2026-11-16</strong>. 本节区分研究指标、工程实践和项目自己的目标. DORA、Google SRE、Prometheus 与 NIST 用于解释定义和方法, 不直接决定本企业的验收阈值; 下文百分比和时间换算均为教学示例, 不是企业实测成绩.</p><table tabindex="0"><thead><tr><th>可核查事实</th><th>对原有回答的补充</th><th>一手来源</th></tr></thead><tbody><tr><td>DORA 当前指南采用五项软件交付绩效指标, 页面更新于 2026-01-05</td><td>不能只背旧“四指标”, 也不能把失败部署恢复时间泛化为所有事故的 MTTR</td><td><a href="https://dora.dev/guides/dora-metrics/" target="_blank" rel="noreferrer">D1</a></td></tr><tr><td>Google SRE 的四个黄金信号为延迟、流量、错误和饱和度</td><td>HTTP 健康还不足以证明报工、队列和 ERP 同步业务健康</td><td><a href="https://sre.google/sre-book/monitoring-distributed-systems/" target="_blank" rel="noreferrer">D2</a></td></tr><tr><td>Prometheus 明确指出, 对各实例预先计算的分位数取平均没有合理的统计意义</td><td>集群 p95 应基于可聚合的分布数据重新计算, 不能平均实例 p95</td><td><a href="https://prometheus.io/docs/practices/histograms/" target="_blank" rel="noreferrer">D3</a></td></tr><tr><td>NIST SP 800-34 Rev. 1 分别定义 RTO 和 RPO</td><td>恢复用时与可恢复数据点是不同维度, “备份成功”不能证明两者达标</td><td><a href="https://nvlpubs.nist.gov/nistpubs/Legacy/SP/nistspecialpublication800-34r1.pdf" target="_blank" rel="noreferrer">D7</a></td></tr></tbody></table><h3 id="_176-现在回答-dora-指标-还只说-部署频率等四项-吗" tabindex="-1">176. 现在回答 DORA 指标, 还只说“部署频率等四项”吗? <a class="header-anchor" href="#_176-现在回答-dora-指标-还只说-部署频率等四项-吗" aria-label="Permalink to &quot;176. 现在回答 DORA 指标, 还只说“部署频率等四项”吗?&quot;">​</a></h3><p><strong>参考回答:</strong> 应说明资料版本. 当前官方指南使用五项: 变更前置时间、部署频率、失败部署恢复时间、变更失败率、部署返工率. 变更前置时间从代码提交到生产部署; 失败部署恢复时间针对失败且需要立即干预的部署; 部署返工率指由生产事故引起的非计划部署占比. 它们衡量应用或服务的交付过程, 不是开发者写了多少行代码. <a href="https://dora.dev/guides/dora-metrics/" target="_blank" rel="noreferrer">D1</a></p><p><strong>追问要点:</strong> 固定服务范围、统计窗口、生产部署事件和失败关联规则, 再比较自身变化. 不把不同产品直接排名, 不为了提高部署频率人为拆无意义发布; 也不能拿开发团队的交付速度替代生产系统的可用性和质量证据.</p><h3 id="_177-系统可用性-99-9-这句话为什么不足以验收" tabindex="-1">177. “系统可用性 99.9%”这句话为什么不足以验收? <a class="header-anchor" href="#_177-系统可用性-99-9-这句话为什么不足以验收" aria-label="Permalink to &quot;177. “系统可用性 99.9%”这句话为什么不足以验收?&quot;">​</a></h3><p><strong>参考回答:</strong> 需要确定 SLI 的测量对象、分子分母、时间窗口、数据来源和排除规则, 再将目标写成 SLO. 例如“30 天内有效报工请求的成功比例达到 99.9%”与“30 天内服务可用时长达到 99.9%”是不同口径. SLA 还涉及与用户的服务约定及未达标后果, 不能与内部 SLO 混称. <a href="https://sre.google/sre-book/service-level-objectives/" target="_blank" rel="noreferrer">D4</a></p><p><strong>教学计算:</strong> 若采用连续 30 天、按不可用时长统计、无排除窗口的模型, <code>30 × 24 × 60 × 0.1% = 43.2 分钟</code>. 若采用请求口径且有 100000 次有效请求, 对应最多 100 次不满足条件的请求. 两者不可互换, 也不能据此允许重复扣料等正确性缺陷.</p><h3 id="_178-两台实例的-p95-分别为-100-ms-和-900-ms-集群-p95-就是-500-ms-吗" tabindex="-1">178. 两台实例的 p95 分别为 100 ms 和 900 ms, 集群 p95 就是 500 ms 吗? <a class="header-anchor" href="#_178-两台实例的-p95-分别为-100-ms-和-900-ms-集群-p95-就是-500-ms-吗" aria-label="Permalink to &quot;178. 两台实例的 p95 分别为 100 ms 和 900 ms, 集群 p95 就是 500 ms 吗?&quot;">​</a></h3><p><strong>参考回答:</strong> 不能这样计算. 分位数描述观测值在分布中的位置, 不包含足够信息用于跨实例取平均; 即使知道各自请求数, 加权平均分位数通常也不正确. 应汇总同口径的原始观测或可聚合直方图, 再计算整体分位数. 使用经典 Histogram 时需保持桶边界兼容, 并注意分桶估算误差. <a href="https://prometheus.io/docs/practices/histograms/" target="_blank" rel="noreferrer">D3</a></p><p><strong>追问要点:</strong> Prometheus 经典直方图可先对同一时间窗口的桶计数速率聚合, 再调用 <code>histogram_quantile</code>. 同时区分成功与失败请求延迟、请求量和饱和度; 很快返回大量错误不代表体验变好. 上述 100 ms、900 ms 只是说明错误算法的假设输入. <a href="https://sre.google/sre-book/monitoring-distributed-systems/" target="_blank" rel="noreferrer">D2</a> <a href="https://prometheus.io/docs/practices/histograms/" target="_blank" rel="noreferrer">D3</a></p><h3 id="_179-数据库字段要改名-怎样让灰度发布期间的新旧代码都能运行" tabindex="-1">179. 数据库字段要改名, 怎样让灰度发布期间的新旧代码都能运行? <a class="header-anchor" href="#_179-数据库字段要改名-怎样让灰度发布期间的新旧代码都能运行" aria-label="Permalink to &quot;179. 数据库字段要改名, 怎样让灰度发布期间的新旧代码都能运行?&quot;">​</a></h3><p><strong>参考回答:</strong> 可采用 Expand-Migrate-Contract: 先扩展兼容结构和接口, 再迁移数据及调用方, 最后在确认旧版本不再使用后收缩旧结构. 双写阶段要明确权威字段、失败处理和一致性核对, 回填不能覆盖更新中的新值. 收缩前要检查旧 APP、长驻 worker、历史队列消息和回退版本, 不能在第一步就删旧列. 这是工程模式, 不是保证所有 DDL 都无锁的承诺. <a href="https://martinfowler.com/bliki/ParallelChange.html" target="_blank" rel="noreferrer">D5</a></p><p><strong>场景追问:</strong> 灰度组与对照组采用可比较的业务流量, 观察错误、延迟和关键业务副作用. 样本量与持续时间需覆盖真实场景, 不能因为少量请求“没报错”就全量发布. 对报工等写操作避免为了对比结果而在生产重复执行; 灰度失败要有暂停及回退条件. <a href="https://sre.google/workbook/canarying-releases/" target="_blank" rel="noreferrer">D6</a></p><h3 id="_180-每晚备份成功-是否就证明-rpo-为零、半小时能恢复" tabindex="-1">180. 每晚备份成功, 是否就证明 RPO 为零、半小时能恢复? <a class="header-anchor" href="#_180-每晚备份成功-是否就证明-rpo-为零、半小时能恢复" aria-label="Permalink to &quot;180. 每晚备份成功, 是否就证明 RPO 为零、半小时能恢复?&quot;">​</a></h3><p><strong>参考回答:</strong> 不能. RPO 关注故障后必须恢复到哪个数据时点, RTO 关注系统恢复阶段可接受的时间. 备份调度、备份完成、备份可读取以及业务可恢复是不同事实. 应在隔离环境演练恢复, 检查备份完整性、日志链、密钥、账号权限和依赖配置, 并以约定的业务验收结果判断恢复是否完成. <a href="https://nvlpubs.nist.gov/nistpubs/Legacy/SP/nistspecialpublication800-34r1.pdf" target="_blank" rel="noreferrer">D7</a></p><p><strong>场景追问:</strong> 教学假设为目标 RPO 15 分钟、RTO 2 小时, 则演练要报告实际恢复到的数据点及各恢复阶段用时. 有数据库日志归档也不能自动证明附件、外部 ERP 单据和审计记录一致; 恢复后还需对账, 避免把旧队列全部重放造成重复副作用.</p><h2 id="五、把面试回答转成可验收证据" tabindex="-1">五、把面试回答转成可验收证据 <a class="header-anchor" href="#五、把面试回答转成可验收证据" aria-label="Permalink to &quot;五、把面试回答转成可验收证据&quot;">​</a></h2><p><strong>教学场景：</strong> 本次版本修复“报工请求超时后重试会重复扣料”。验收目标要同时覆盖业务正确性、故障恢复与可追踪性，不能只写“接口能返回 200”。</p><table tabindex="0"><thead><tr><th>风险或需求</th><th>如何验证</th><th>应保留什么证据</th></tr></thead><tbody><tr><td>同一操作重复扣料</td><td>使用相同键发起独立并发请求，并模拟提交后响应丢失</td><td>请求键、响应、报工与流水数量、库存前后值</td></tr><tr><td>不同操作争抢库存</td><td>两个独立连接竞争不足以同时满足的库存</td><td>成功与拒绝结果、最终库存、事务失败记录</td></tr><tr><td>跨工厂越权</td><td>用 A 工厂身份访问 B 工厂的详情、导出和附件</td><td>拒绝结果及不存在业务副作用的核对</td></tr><tr><td>数据库成功但 ERP 未确认</td><td>模拟远端超时、重复回执及恢复查询</td><td>本地提交、待同步、远端确认之间的完整状态记录</td></tr><tr><td>新代码与旧任务不兼容</td><td>用旧版本任务载荷在升级后执行</td><td>任务版本、处理结果及失败恢复记录</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">特别解释：测试步骤、断言与证据</p><p>**步骤（Steps）**描述怎样触发；**断言（Assertion）**说明结果必须满足什么；**证据（Evidence）**记录实际发生了什么。例如“点两次按钮”只是步骤，“库存只扣一次”是断言，关联请求与数据库流水的测试记录才是证据。截图可以辅助说明界面，通常不能单独证明事务正确。</p></div><p><strong>练习交付物：</strong> 选一个真实或明确标注为练习的功能，写一条需求、一项风险、一个正常用例、两个失败用例和一个回退条件，并将它们关联到同一版本。尚未执行的用例写“待验证”，不要把计划当结果。</p><h2 id="关键术语与专业解释" tabindex="-1">关键术语与专业解释 <a class="header-anchor" href="#关键术语与专业解释" aria-label="Permalink to &quot;关键术语与专业解释&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>专业解释</th><th>面试边界</th></tr></thead><tbody><tr><td>DORA Metrics</td><td>用于衡量应用或服务软件交付表现的一组研究指标, 当前指南为五项</td><td>不把交付指标当个人产能指标, 也不替代服务可靠性指标. <a href="https://dora.dev/guides/dora-metrics/" target="_blank" rel="noreferrer">D1</a></td></tr><tr><td>Failed Deployment Recovery Time</td><td>从需要立即干预的失败部署中恢复所需的时间</td><td>与所有原因故障的平均恢复时间不是同一统计范围. <a href="https://dora.dev/guides/dora-metrics/" target="_blank" rel="noreferrer">D1</a></td></tr><tr><td>Deployment Rework Rate</td><td>由生产事故引起的非计划部署占比</td><td>不等于所有需求返工比例或代码修改比例. <a href="https://dora.dev/guides/dora-metrics/" target="_blank" rel="noreferrer">D1</a></td></tr><tr><td>SLI / SLO / SLA</td><td>服务水平指标、目标与服务水平协议; 分别回答如何测量、达到什么值、与用户约定什么及其后果</td><td>必须配套时间窗口和测量规则. <a href="https://sre.google/sre-book/service-level-objectives/" target="_blank" rel="noreferrer">D4</a></td></tr><tr><td>Error Budget</td><td>在所选 SLO 口径下允许不满足目标条件的额度</td><td>是可靠性与变更决策的输入, 不是违规放行或数据错误的许可. <a href="https://sre.google/sre-book/service-level-objectives/" target="_blank" rel="noreferrer">D4</a></td></tr><tr><td>p95 / p99</td><td>第 95 / 99 百分位数, 用于描述尾部延迟等分布特征</td><td>不是平均值, 不能简单跨实例平均. <a href="https://sre.google/sre-book/monitoring-distributed-systems/" target="_blank" rel="noreferrer">D2</a> <a href="https://prometheus.io/docs/practices/histograms/" target="_blank" rel="noreferrer">D3</a></td></tr><tr><td>Histogram / Summary</td><td>Prometheus 中基于分布计数或客户端预计算分位数等方式表达观测数据的指标类型</td><td>Summary 的预计算分位数不能像直方图桶那样聚合, 但其 sum/count 仍可聚合. <a href="https://prometheus.io/docs/practices/histograms/" target="_blank" rel="noreferrer">D3</a></td></tr><tr><td>Canary Release</td><td>先向有限生产范围发布变更, 与对照范围比较并决定是否继续的发布方法</td><td>小比例流量不自动等于代表性样本. <a href="https://sre.google/workbook/canarying-releases/" target="_blank" rel="noreferrer">D6</a></td></tr><tr><td>Expand-Migrate-Contract</td><td>通过扩展、迁移、收缩三个阶段降低接口或结构变更不兼容的工程模式</td><td>需要最终完成收缩, 不能无限保留两套相互漂移的数据. <a href="https://martinfowler.com/bliki/ParallelChange.html" target="_blank" rel="noreferrer">D5</a></td></tr><tr><td>RTO / RPO</td><td>Recovery Time Objective 与 Recovery Point Objective, 分别约束恢复阶段时长和应恢复到的数据时点</td><td>需从业务影响推导并演练验证, 不由备份任务绿灯自动证明. <a href="https://nvlpubs.nist.gov/nistpubs/Legacy/SP/nistspecialpublication800-34r1.pdf" target="_blank" rel="noreferrer">D7</a></td></tr></tbody></table><h3 id="测试与交付关键词补充" tabindex="-1">测试与交付关键词补充 <a class="header-anchor" href="#测试与交付关键词补充" aria-label="Permalink to &quot;测试与交付关键词补充&quot;">​</a></h3><table tabindex="0"><thead><tr><th>关键词</th><th>通俗解释与本篇场景</th><th>必须区分的概念</th></tr></thead><tbody><tr><td>单元 / 集成 / E2E 测试</td><td>分别验证局部规则、组件协作和端到端用户流程</td><td>测试越靠外越不等于所有内部边界都已覆盖</td></tr><tr><td>UAT（User Acceptance Testing）</td><td>用户验收测试，由业务代表按约定场景确认是否满足使用需求</td><td>业务验收不替代并发、权限和恢复验证</td></tr><tr><td>Mock / Fake / Stub</td><td>常见约定中，Mock 强调交互期望，Fake 提供简化实现，Stub 返回预设响应</td><td>库命名不完全一致；Laravel 的 Fake 名称不意味着连到了真实供应商</td></tr><tr><td>回归测试（Regression Testing）</td><td>修改后重新检查可能受影响的已有行为</td><td>不等于只测试本次新增按钮</td></tr><tr><td>RTM（Requirements Traceability Matrix）</td><td>需求追踪矩阵，连接需求、风险、实现与测试结果</td><td>是检查遗漏和变更影响的关系，不只是需求清单</td></tr><tr><td>CI / 持续交付 / 持续部署</td><td>CI 自动验证集成变更；持续交付保持可发布；持续部署进一步自动发布通过门禁的变更</td><td>“CD”可能指后两者，应先说明团队含义</td></tr><tr><td>冒烟测试（Smoke Test）</td><td>发布后快速验证关键路径，及时发现明显故障</td><td>少量关键场景通过不代表完整回归通过</td></tr><tr><td>可观测性（Observability）</td><td>通过日志、指标、追踪等信号理解运行状态及故障</td><td>有监控面板不等于能够关联一次报工的全过程</td></tr><tr><td>Runbook / Postmortem</td><td>前者是可执行的运维处置手册，后者是基于事实的故障复盘</td><td>“重启服务”需要前置判断与验证；复盘还要跟进改进项</td></tr></tbody></table><h2 id="一手资料与核查口径" tabindex="-1">一手资料与核查口径 <a class="header-anchor" href="#一手资料与核查口径" aria-label="Permalink to &quot;一手资料与核查口径&quot;">​</a></h2><ul><li><a href="https://dora.dev/guides/dora-metrics/" target="_blank" rel="noreferrer">D1. DORA: Software Delivery Performance Metrics</a>, 官方研究指南, 不引用未核实的行业分档数字.</li><li><a href="https://sre.google/sre-book/monitoring-distributed-systems/" target="_blank" rel="noreferrer">D2. Google SRE: Monitoring Distributed Systems</a>, 四个黄金信号及延迟分布.</li><li><a href="https://prometheus.io/docs/practices/histograms/" target="_blank" rel="noreferrer">D3. Prometheus: Histograms and Summaries</a>, 分位数计算与聚合边界.</li><li><a href="https://sre.google/sre-book/service-level-objectives/" target="_blank" rel="noreferrer">D4. Google SRE: Service Level Objectives</a>, SLI、SLO、SLA 和误差预算.</li><li><a href="https://martinfowler.com/bliki/ParallelChange.html" target="_blank" rel="noreferrer">D5. Martin Fowler: Parallel Change</a>, 工程模式说明, 不是法规或产品 SLA.</li><li><a href="https://sre.google/workbook/canarying-releases/" target="_blank" rel="noreferrer">D6. Google SRE Workbook: Canarying Releases</a>, 灰度对照与样本代表性.</li><li><a href="https://nvlpubs.nist.gov/nistpubs/Legacy/SP/nistspecialpublication800-34r1.pdf" target="_blank" rel="noreferrer">D7. NIST SP 800-34 Rev. 1: Contingency Planning Guide for Federal Information Systems</a>, 用于核对恢复目标术语, 不自动将美国联邦系统要求套到本企业.</li></ul><h2 id="自测与复习安排" tabindex="-1">自测与复习安排 <a class="header-anchor" href="#自测与复习安排" aria-label="Permalink to &quot;自测与复习安排&quot;">​</a></h2><table tabindex="0"><thead><tr><th>复习轮次</th><th>内容</th><th>验收方式</th></tr></thead><tbody><tr><td>第一轮</td><td>01—60: PHP、Laravel、MySQL</td><td>能说清请求链路、事务、幂等、索引和扣料并发, 区分锁超时与死锁</td></tr><tr><td>第二轮</td><td>61—120: 集成、设备、生产、电子记录</td><td>能画出数据链路, 解释重复、乱序、补偿及记录更正, 说明法规适用边界</td></tr><tr><td>第三轮</td><td>121—150: UniApp 与移动端</td><td>能说明登录、扫码、离线队列、冲突和跨端限制, 核对存储与文件生命周期</td></tr><tr><td>第四轮</td><td>151—180: 验证、上线、协作</td><td>用真实项目完成故障排查和三分钟项目介绍, 定义交付指标与恢复目标</td></tr></tbody></table><p>时间有限时, 先看 <strong>10、13、15—18、34—35、40—48、65、69—77、91—94、102—109、127—139、152—153、159—165、174—175</strong>. 这些是原有核心题按新编号映射的清单. 再按薄弱领域补看各篇进阶题: <strong>26—30、56—60、86—90、116—120、146—150、176—180</strong>. 每题先用自己的话回答, 再对照参考内容检查遗漏; 不要只背术语.</p><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="./uniapp-mobile-interview.html">上一篇：UniApp、小程序与 APP（121—150）</a></li><li><a href="./laravel-php-interview.html">从第一篇开始：Laravel 与后端开发（01—30）</a></li><li><a href="./../">返回 PHP 面试指南</a></li><li><a href="./../soft/requirement-translation.html">既有专题：技术沟通与需求转化</a></li></ul>',114)])])}const c=r(s,[["render",n]]);export{b as __pageData,c as default};
